func Sublist(l1, l2 []int) Relation {
	if len(l1) == len(l2) {
		if contains(l1, l2) {
			return RelationEqual
		}
		return RelationUnequal
	}
	if len(l1) < len(l2) {
		if contains(l2, l1) {
			return RelationSublist
		}
		return RelationUnequal
	}
	if contains(l1, l2) {
		return RelationSuperlist
	}
	return RelationUnequal
}

// contains reports whether l contains a contiguous sub-sequence equal to sub.
func contains(l, sub []int) bool {
	if len(sub) == 0 {
		return true
	}
	for i := 0; i+len(sub) <= len(l); i++ {
		match := true
		for j := range sub {
			if l[i+j] != sub[j] {
				match = false
				break
			}
		}
		if match {
			return true
		}
	}
	return false
}

